import java.util.*;
public class Solution{public static void main(String[]a){Scanner sc=new Scanner(System.in);int n=sc.nextInt();int[]h=new int[n],L=new int[n],R=new int[n];for(int i=0;i<n;i++)h[i]=sc.nextInt();L[0]=h[0];for(int i=1;i<n;i++)L[i]=Math.max(L[i-1],h[i]);R[n-1]=h[n-1];for(int i=n-2;i>=0;i--)R[i]=Math.max(R[i+1],h[i]);long w=0;for(int i=0;i<n;i++)w+=Math.min(L[i],R[i])-h[i];System.out.println(w);}}
